import * as signalR from '@microsoft/signalr';

class SignalRService {
  constructor() {
    this.connection = null;
    this.isConnected = false;
  }

  async startConnection(token) {
    if (this.connection) {
      console.log('SignalR уже подключён');
      return this.isConnected;
    }

    try {
      this.connection = new signalR.HubConnectionBuilder()
        .withUrl(`http://localhost:5000/chathub?access_token=${token}`, {
          skipNegotiation: true,
          transport: signalR.HttpTransportType.WebSockets
        })
        .withAutomaticReconnect([0, 2000, 5000, 10000, 30000])
        .configureLogging(signalR.LogLevel.Information)
        .build();

      // 🔥 Обработчики подключения
      this.connection.onclose((error) => {
        console.log('SignalR отключён:', error);
        this.isConnected = false;
      });

      this.connection.onreconnecting((error) => {
        console.log('SignalR переподключение...', error);
        this.isConnected = false;
      });

      this.connection.onreconnected((connectionId) => {
        console.log('SignalR переподключён:', connectionId);
        this.isConnected = true;
      });

      // 🔥 Запускаем подключение
      await this.connection.start();
      this.isConnected = true;
      
      console.log('✅ SignalR подключён успешно');
      return true;
    } catch (error) {
      console.error('❌ Ошибка подключения SignalR:', error);
      this.isConnected = false;
      return false;
    }
  }

  async sendMessage(recipientId, message) {
    if (!this.connection || !this.isConnected) {
      throw new Error('SignalR не подключён');
    }

    try {
      await this.connection.invoke('SendMessage', recipientId, message);
      return true;
    } catch (error) {
      console.error('Ошибка отправки сообщения:', error);
      throw error;
    }
  }

  onMessage(callback) {
    if (this.connection) {
      this.connection.on('ReceiveMessage', callback);
    }
  }

  onMessageSent(callback) {
    if (this.connection) {
      this.connection.on('MessageSent', callback);
    }
  }

  onConversationUpdate(callback) {
    if (this.connection) {
      this.connection.on('ConversationUpdated', callback);
    }
  }

  onUserStatus(callback) {
    if (this.connection) {
      this.connection.on('UserStatusChanged', callback);
    }
  }

  stopConnection() {
    if (this.connection) {
      this.connection.stop();
      this.connection = null;
      this.isConnected = false;
    }
  }

  isConnected() {
    return this.isConnected && this.connection?.state === signalR.HubConnectionState.Connected;
  }
}

export default new SignalRService();
